import { defineConfig } from 'vitest/config';
export default defineConfig({ test: { include: ['src/**/*.test.ts', 'scripts/**/*.test.ts'] } });
import { readdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';

export async function sourceFiles(
  folder: string,
): Promise<readonly { path: string; text: string }[]> {
  const result: { path: string; text: string }[] = [];
  for (const entry of await readdir(folder, { withFileTypes: true })) {
    const path = join(folder, entry.name);
    if (entry.isDirectory()) result.push(...(await sourceFiles(path)));
    else if (entry.isFile()) result.push({ path, text: await readFile(path, 'utf8') });
    else throw new Error('Source contains a link or special file.');
  }
  return result;
}
import { readFile } from 'node:fs/promises';
import { createServer } from 'node:http';
import { fileURLToPath } from 'node:url';

export async function serveArtifact() {
  const html = await readFile(new URL('../dist/index.html', import.meta.url));
  const server = createServer((request, response) => {
    if (request.url !== '/') {
      response.writeHead(404).end();
      return;
    }
    response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }).end(html);
  });
  await new Promise<void>((ready, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', ready);
  });
  const address = server.address();
  if (!address || typeof address === 'string') throw new Error('Expected a private test port.');
  return {
    url: `http://127.0.0.1:${address.port}/`,
    close: () =>
      new Promise<void>((closed, reject) => {
        server.close((error) => {
          if (error) reject(error);
          else closed();
        });
      }),
  };
}

